\version "2.27.2"
% automatically converted by musicxml2ly from 46e-PickupMeasure-SecondVoiceStartsLater.xml
\pointAndClickOff

\header {
  texidoc = "Using <backup> it is possible to have ‘incomplete’ measure lengths.
    This test starts with a quarter note upbeat and a whole note for voice 1 in
    the first measure, and voice 2 contains only a quarter note starting at the
    second beat. The second measure contains whole notes for both voices. Note
    that there is a discontinuity in the MusicXML timing: voice 2 ‘jumps’ from
    the single quarter note to the whole note in the second measure."
}
\layout {
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c'' {
  \partial 4 \once \omit Staff.TimeSignature \oneVoice c4 c1 | % 1
  \voiceOne c1 }

PartPOneVoiceTwo = \relative c' {
  \partial 4 s2 c4 s2 | % 1
  c1 }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \voiceOne \PartPOneVoiceOne
        }
        \context Voice = "PartPOneVoiceTwo" {
          \voiceTwo \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
